// Builds the personalised review link + the message to send.
// Change this one line if your review page lives somewhere else:
const BASE = 'https://beauty-bareg.net/pages/reviews';

const clean = (v) => (v === undefined || v === null) ? '' : String(v).trim();

const out = [];

for (const item of $input.all()) {
  // Webhook node puts the POSTed JSON under .body
  const b = item.json.body || item.json;

  const name  = clean(b.name || b.customer_name || b.first_name);
  const email = clean(b.email || b.customer_email);
  const order = clean(b.order_number || b.order || b.order_id);
  const lang  = (clean(b.lang || b.language) || 'ar').toLowerCase();

  // ---- the id that ends up next to the name on the dashboard ----
  // Priority: explicit id  →  order number  →  error.
  let cid = clean(b.customer_id || b.cid || b.id);
  if (!cid && order) cid = 'ORD-' + order.replace(/[^A-Za-z0-9_-]/g, '');
  if (!cid) {
    throw new Error('Nothing to identify the customer with. Send customer_id or order_number.');
  }
  cid = cid.slice(0, 64);

  const link = BASE + '?cid=' + encodeURIComponent(cid);

  // ---- phone → WhatsApp format (digits only, Egypt default) ----
  let phone = clean(b.phone || b.whatsapp || b.customer_phone).replace(/\D/g, '');
  if (phone.startsWith('00')) phone = phone.slice(2);
  if (phone.startsWith('0'))  phone = '20' + phone.slice(1);   // 01xxxxxxxxx → 201xxxxxxxxx

  // ---- how to send it ----
  const channel = (clean(b.channel) || (phone ? 'whatsapp' : email ? 'email' : 'link')).toLowerCase();

  // ---- message text ----
  const hi = lang === 'en'
    ? (name ? 'Hi ' + name + ',' : 'Hi,')
    : (name ? 'أهلاً ' + name + '،' : 'أهلاً،');

  const message = lang === 'en'
    ? hi + '\n\nThank you for your order' + (order ? ' #' + order : '') + ' from Beauty Bareg 🧡\n'
       + "We'd love to hear how it went — it takes less than a minute:\n" + link
    : hi + '\n\nشكراً لطلبك' + (order ? ' رقم ' + order : '') + ' من Beauty Bareg 🧡\n'
       + 'ياريت تقيّم تجربتك معانا، مش هياخد منك دقيقة:\n' + link;

  const subject = lang === 'en'
    ? 'How was your Beauty Bareg order?'
    : 'إزاي كانت تجربتك مع Beauty Bareg؟';

  out.push({
    json: { customer_id: cid, name, email, phone, order_number: order, lang, channel, link, subject, message }
  });
}

return out;
